const OPENROUTER_LOCAL_STORAGE_KEY = "openrouter_api_key";
const GEMINI_LOCAL_STORAGE_KEY = "geminiApiKey";
let OPENROUTER_API_KEY = null;

async function initGeminiSdk() {
  let t = null;
  try {
    t = await readStoredText(OPENROUTER_LOCAL_STORAGE_KEY);
  } catch (e) {}
  if (!t) {
    try {
      t = await readStoredText(GEMINI_LOCAL_STORAGE_KEY);
    } catch (e) {}
  }
  if (t && typeof t === "string") {
    OPENROUTER_API_KEY = t.trim();
  }
}

async function setGeminiApiKey(t) {
  if (t && typeof t === "string") {
    const k = t.trim();
    await storeText(OPENROUTER_LOCAL_STORAGE_KEY, k);
    await storeText(GEMINI_LOCAL_STORAGE_KEY, k);
    OPENROUTER_API_KEY = k;
  }
}

async function removeGeminiApiKey() {
  try {
    await localStorage.removeItem(OPENROUTER_LOCAL_STORAGE_KEY);
  } catch (e) {}
  try {
    await localStorage.removeItem(GEMINI_LOCAL_STORAGE_KEY);
  } catch (e) {}
  OPENROUTER_API_KEY = null;
}

async function getGeminiApiKey() {
  return OPENROUTER_API_KEY;
}
window.getGeminiApiKey = getGeminiApiKey;
window.setGeminiApiKey = setGeminiApiKey;

function uint8ArrayToBase64(bytes) {
  let binary = "";
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

async function fetchOpenRouterBalance() {
  const apiKey = OPENROUTER_API_KEY || (await getGeminiApiKey());
  if (!apiKey) {
    return {
      balance: "$0.00",
      numeric: 0,
      label: "No API Key"
    };
  }

  const headers = {
    "Authorization": `Bearer ${apiKey}`,
    "HTTP-Referer": "https://github.com/arnaudnjita/astria-ps-plugin",
    "X-Title": "Astria Nano Banana Photoshop Plugin"
  };

  // 1. Try account credits endpoint (GET /api/v1/credits)
  try {
    const res = await fetch("https://openrouter.ai/api/v1/credits", { headers });
    if (res.ok) {
      const json = await res.json();
      if (json && json.data) {
        const total = Number(json.data.total_credits);
        const used = Number(json.data.total_usage || 0);
        if (!isNaN(total)) {
          const remaining = Math.max(0, total - used);
          return {
            balance: `$${remaining.toFixed(2)}`,
            numeric: remaining,
            label: json.data.label || "OpenRouter"
          };
        }
      }
    }
  } catch (e) {
    console.warn("[OpenRouter] /api/v1/credits query error:", e);
  }

  // 2. Try API key endpoint (GET /api/v1/auth/key)
  try {
    const res = await fetch("https://openrouter.ai/api/v1/auth/key", { headers });
    if (res.ok) {
      const json = await res.json();
      if (json && json.data) {
        const d = json.data;
        const keyLabel = d.label || "OpenRouter Key";
        if (d.limit_remaining !== null && d.limit_remaining !== undefined) {
          const rem = Math.max(0, Number(d.limit_remaining));
          return {
            balance: `$${rem.toFixed(2)}`,
            numeric: rem,
            label: keyLabel
          };
        }
        if (d.limit !== null && d.limit !== undefined) {
          const rem = Math.max(0, Number(d.limit) - Number(d.usage || 0));
          return {
            balance: `$${rem.toFixed(2)}`,
            numeric: rem,
            label: keyLabel
          };
        }
        if (d.is_free_tier) {
          return {
            balance: "Free Tier",
            numeric: 0,
            label: keyLabel
          };
        }
        if (d.usage !== undefined && d.usage !== null) {
          return {
            balance: `Used $${Number(d.usage).toFixed(2)}`,
            numeric: Number(d.usage),
            label: keyLabel
          };
        }
        return {
          balance: "Active",
          numeric: 10,
          label: keyLabel
        };
      }
    }
  } catch (e) {
    console.warn("[OpenRouter] /api/v1/auth/key query error:", e);
  }

  return {
    balance: "$0.00",
    numeric: 0,
    label: "OpenRouter"
  };
}
window.fetchOpenRouterBalance = fetchOpenRouterBalance;

async function editImageWithGemini(targetModel, promptText, imageParts, options = {}) {
  const apiKey = OPENROUTER_API_KEY;
  if (!apiKey) {
    throw new Error("Please enter your OpenRouter API key first to generate images.");
  }

  const inputReferences = [];
  if (Array.isArray(imageParts)) {
    for (const part of imageParts) {
      if (!part) continue;
      const mime = part.mimeType || "image/png";
      let base64 = "";
      if (typeof part.data === "string") {
        base64 = part.data.startsWith("data:") ? part.data : `data:${mime};base64,${part.data}`;
      } else if (part.data instanceof ArrayBuffer) {
        base64 = `data:${mime};base64,${uint8ArrayToBase64(new Uint8Array(part.data))}`;
      } else if (part.data && part.data.buffer instanceof ArrayBuffer) {
        base64 = `data:${mime};base64,${uint8ArrayToBase64(new Uint8Array(part.data.buffer))}`;
      }
      if (base64) {
        inputReferences.push({
          type: "image_url",
          image_url: { url: base64 }
        });
      }
    }
  }

  let modelSlug = targetModel;
  if (modelSlug.startsWith("models/")) {
    modelSlug = modelSlug.replace("models/", "");
  }

  const payload = {
    model: modelSlug,
    prompt: promptText,
    n: 1
  };

  if (options.aspectRatio) {
    payload.aspect_ratio = options.aspectRatio;
  }

  // Model-specific parameters aligned to OpenRouter live image model schemas:
  const isOpenAI = modelSlug.startsWith("openai/");
  const isGrok = modelSlug.startsWith("x-ai/");
  const noResolution = isOpenAI || modelSlug.startsWith("recraft/") || modelSlug === "black-forest-labs/flux.2-pro";

  if ((isOpenAI || isGrok) && options.quality) {
    payload.quality = String(options.quality).toLowerCase();
  } else if (isOpenAI) {
    payload.quality = "medium";
  }

  if (!noResolution && options.imageSize) {
    payload.resolution = options.imageSize;
  }

  if (isOpenAI || modelSlug.startsWith("sourceful/") || modelSlug === "black-forest-labs/flux.2-pro") {
    payload.output_format = "png";
  }

  if (inputReferences.length > 0) {
    payload.input_references = inputReferences;
  }

  console.log("[OpenRouter] Calling /api/v1/images with payload:", JSON.stringify({
    model: payload.model,
    prompt: payload.prompt,
    aspect_ratio: payload.aspect_ratio,
    resolution: payload.resolution,
    quality: payload.quality,
    references: inputReferences.length
  }));

  const headers = {
    "Content-Type": "application/json",
    "Authorization": `Bearer ${apiKey}`,
    "HTTP-Referer": "https://github.com/arnaudnjita/astria-ps-plugin",
    "X-Title": "Astria Nano Banana Photoshop Plugin"
  };

  const response = await fetch("https://openrouter.ai/api/v1/images", {
    method: "POST",
    headers: headers,
    body: JSON.stringify(payload),
    ...(options.signal ? { signal: options.signal } : {})
  });

  if (!response.ok) {
    let errMessage = "";
    try {
      const errJson = await response.json();
      errMessage = errJson?.error?.message || errJson?.message || JSON.stringify(errJson);
    } catch (e) {
      errMessage = `HTTP error ${response.status}: ${response.statusText}`;
    }
    throw new Error(`OpenRouter API Error: ${errMessage}`);
  }

  const resJson = await response.json();
  const item = resJson?.data && resJson.data[0];
  if (!item) {
    throw new Error("No image data returned from OpenRouter API.");
  }

  let deductedCost = 0;
  if (resJson.usage && typeof resJson.usage.cost === "number" && resJson.usage.cost > 0) {
    deductedCost = resJson.usage.cost;
  } else if (typeof options.costNumber === "number" && options.costNumber > 0) {
    deductedCost = options.costNumber;
  } else if (options.cost) {
    deductedCost = parseFloat(String(options.cost).replace(/[^0-9.]/g, "")) || 0;
  }
  if (deductedCost > 0 && typeof window.deductOpenRouterBalance === "function") {
    window.deductOpenRouterBalance(deductedCost);
  }

  if (item.b64_json) {
    const mediaType = item.media_type || "image/png";
    return `data:${mediaType};base64,${item.b64_json}`;
  }

  if (item.url) {
    return item.url;
  }

  throw new Error("Unexpected OpenRouter image response format.");
}
